// Original procedural artwork reconstructed for this fan-made first-person prototype.
// Visual references: Arknights default operator outfits and Reunion unit silhouettes.
function poly(c,points,fill,stroke='#11171d',width=2){c.beginPath();points.forEach((p,i)=>i?c.lineTo(...p):c.moveTo(...p));c.closePath();c.fillStyle=fill;c.fill();if(stroke){c.strokeStyle=stroke;c.lineWidth=width;c.stroke()}}
function line(c,points,color,width=2){c.beginPath();points.forEach((p,i)=>i?c.lineTo(...p):c.moveTo(...p));c.strokeStyle=color;c.lineWidth=width;c.stroke()}
function gradient(c,x,y,x2,y2,a,b){const g=c.createLinearGradient(x,y,x2,y2);g.addColorStop(0,a);g.addColorStop(1,b);return g}
function makeTile(kind){const a=document.createElement('canvas');a.width=a.height=128;const c=a.getContext('2d');const img=c.createImageData(128,128);let seed=kind.length*701;for(let i=0;i<img.data.length;i+=4){seed=(seed*1664525+1013904223)>>>0;let v=(seed>>>24)%17-8,base=kind==='snow'?137:kind==='metal'?62:kind==='wall'?83:kind==='route'?79:90;img.data[i]=base+v;img.data[i+1]=base+v+(kind==='snow'?8:0);img.data[i+2]=base+v+4;img.data[i+3]=255}c.putImageData(img,0,0);c.lineWidth=3;c.strokeStyle='#252c32';c.strokeRect(1,1,126,126);c.strokeStyle='#b3b7b544';c.strokeRect(5,5,118,118);
if(kind==='metal'){c.fillStyle='#252d34';c.fillRect(13,14,102,100);for(let y=17;y<110;y+=9){c.fillStyle='#89949b';c.fillRect(17,y,94,2)}for(let x=20;x<110;x+=18)c.fillRect(x,14,3,100)}
if(kind==='route'){c.fillStyle='#3d4247';c.fillRect(6,8,116,17);c.save();c.beginPath();c.rect(6,8,116,17);c.clip();for(let i=-20;i<150;i+=22)poly(c,[[i,8],[i+10,8],[i+27,25],[i+17,25]],'#c2a85f',null);c.restore();line(c,[[50,91],[66,72],[82,91]],'#b2b2a66b',5);c.fillStyle='#c7b684';c.font='10px monospace';c.fillText('R-03',11,113)}
if(kind==='wall'){c.fillStyle='#b3b2aa';c.fillRect(7,8,114,19);c.fillStyle='#242b33';c.fillRect(7,30,114,10);c.fillStyle='#34434c';c.fillRect(9,48,110,69);c.strokeStyle='#78828b';c.strokeRect(12,51,104,63);for(let y=58;y<109;y+=10){c.fillStyle='#202932';c.fillRect(23,y,80,4)}c.fillStyle='#c0a65d';c.fillRect(9,100,9,17);c.fillRect(109,100,9,17)}
if(kind==='concrete'||kind==='snow'){line(c,[[17,27],[36,43],[31,52],[48,69],[46,86],[66,107]],'#30373a85',1);line(c,[[32,52],[17,63],[9,62]],'#30373a85',1);c.fillStyle='#181f2922';c.fillRect(84,21,22,48);c.fillStyle='#c6c9c044';c.fillRect(85,22,21,2)}
for(const x of [9,119])for(const y of [9,119]){c.fillStyle='#252d33';c.beginPath();c.arc(x,y,2,0,7);c.fill()}return {canvas:a,pixels:c.getImageData(0,0,128,128).data}}
const MATERIALS={concrete:makeTile('concrete'),route:makeTile('route'),metal:makeTile('metal'),wall:makeTile('wall'),snow:makeTile('snow')};
const groundCanvas=document.createElement('canvas');let groundBuffer;
function drawGround(horizon){const gw=Math.ceil(W/2),gh=Math.ceil(H/2);if(groundCanvas.width!==gw||groundCanvas.height!==gh||!groundBuffer){groundCanvas.width=gw;groundCanvas.height=gh;groundBuffer=groundCanvas.getContext('2d').createImageData(gw,gh)}const out=groundBuffer.data,ca=Math.cos(p.a),sa=Math.sin(p.a),h=horizon/2;out.fill(0);for(let y=Math.max(0,Math.floor(h)+1);y<gh;y++){const depth=H*.365/((y-h)*2),shade=Math.max(.23,1-depth/29);for(let x=0;x<gw;x++){const side=(x/gw*2-1)*Math.tan(cameraFov/2)*depth,wx=p.x+ca*depth-sa*side,wy=p.y+sa*depth+ca*side,tx=Math.floor(wx),ty=Math.floor(wy),tile=map.rows[ty]?.[tx],kind=tile==='R'?'route':tile==='B'?'metal':mapIdx?'snow':(tx*3+ty*7)%9===0?'metal':'concrete',pixels=MATERIALS[kind].pixels,u=((wx-tx)*128)|0,v=((wy-ty)*128)|0,src=(v*128+u)*4,dst=(y*gw+x)*4;out[dst]=pixels[src]*shade;out[dst+1]=pixels[src+1]*shade;out[dst+2]=pixels[src+2]*shade;out[dst+3]=255}}groundCanvas.getContext('2d').putImageData(groundBuffer,0,0);ctx.imageSmoothingEnabled=false;ctx.drawImage(groundCanvas,0,0,W,H);ctx.imageSmoothingEnabled=true}
function drawWallColumn(x,r,d,h,horizon,step){const fx=r.x-Math.floor(r.x),fy=r.y-Math.floor(r.y),onX=Math.min(fx,1-fx)<.055,u=((onX?r.y:r.x)%1+1)%1;ctx.drawImage(MATERIALS.wall.canvas,Math.floor(u*127),0,1,128,x,horizon-h*.5,step+1,h);ctx.fillStyle=`rgba(8,15,24,${Math.min(.83,d/28)+(onX?.08:0)})`;ctx.fillRect(x,horizon-h*.5,step+1,h)}
function drawCrystal(size){const c=ctx;c.save();c.scale(size/130,size/130);c.fillStyle='#0d1119aa';c.beginPath();c.ellipse(0,0,36,8,0,0,7);c.fill();for(const [x,y,s] of [[-24,0,.6],[10,1,1],[35,1,.5]]){c.save();c.translate(x,y);c.scale(s,s);poly(c,[[-18,0],[-21,-62],[-3,-105],[17,-70],[23,-15]],'#171b29','#596273',2);poly(c,[[-3,-105],[17,-70],[23,-15],[0,-29]],'#373346','#77768b',1);line(c,[[-11,-45],[-5,-70],[7,-59],[11,-27]],'#c5834d',2);c.restore()}c.restore()}
